package campfire.rails

import com.fasterxml.jackson.databind.JsonNode
import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.databind.SerializationFeature
import java.io.File
import java.time.Duration
import java.time.Instant
import java.util.HexFormat
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertFalse
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue

/**
 * Golden-vector tests against `vectors/rails_compat.json` (generated by the reference app with
 * `reference-tools/rails_compat_vectors.rb`), mirroring `once-campfire-rust/crates/rails_compat/src/golden.rs`
 * test for test. The last test also writes what Kotlin generates to
 * `rails-compat/build/rails_compat_kotlin_output.json`, in the shape
 * `reference-tools/rails_compat_verify_rust.rb` checks with Rails itself.
 */
class GoldenTest {
    private companion object {
        val VECTORS_DIR = File(System.getProperty("campfire.vectors") ?: error("campfire.vectors is not set"))
        val MAPPER = ObjectMapper()
        val VECTORS: JsonNode = MAPPER.readTree(File(VECTORS_DIR, "rails_compat.json"))
        val SECRETS = Secrets(str(VECTORS["secret_key_base"]))
        val HEX: HexFormat = HexFormat.of()

        /** A dotted path into the vectors. */
        fun v(path: String): JsonNode = path.split('.').fold(VECTORS) { value, key -> value[key] ?: error("no $path") }

        fun cases(path: String): List<JsonNode> = v(path).also { check(it.isArray) { "$path is an array" } }.toList()

        fun str(value: JsonNode): String = value.also { check(it.isTextual) { "expected a string, got $it" } }.asText()

        fun optStr(value: JsonNode?): String? = if (value != null && value.isTextual) value.asText() else null

        fun time(value: JsonNode): Instant = Instant.parse(str(value))

        fun optTime(value: JsonNode?): Instant? = optStr(value)?.let(Instant::parse)

        fun now(): Instant = time(v("now"))

        fun label(case: JsonNode): String = "case \"${case["case"]?.asText() ?: ""}\""

        /** A vector value in the [RailsJson] value model, to compare with what the port returns. */
        fun model(node: JsonNode?): Any? = when {
            node == null || node.isNull || node.isMissingNode -> null
            node.isTextual -> node.asText()
            node.isBoolean -> node.asBoolean()
            node.isBigInteger -> node.bigIntegerValue().let { if (it.bitLength() < 64) it.toLong() else it }
            node.isIntegralNumber -> node.asLong()
            node.isNumber -> node.asDouble()
            node.isArray -> node.map { model(it) }
            node.isObject -> LinkedHashMap<String, Any?>().also { map -> node.properties().forEach { (k, v) -> map[k] = model(v) } }
            else -> error("unexpected $node")
        }
    }

    @Test
    fun keyGenerator() {
        for (case in cases("key_generator")) {
            val key = SECRETS.keyGenerator.generateKey(str(case["salt"]), case["length"].asInt())
            assertEquals(str(case["key_hex"]), HEX.formatHex(key), "salt ${case["salt"]}")
        }
    }

    @Test
    fun cookieEscaping() {
        for (case in cases("cookie_escaping")) {
            optStr(case["raw"])?.let { raw -> assertEquals(str(case["wire"]), Cookies.escape(raw), "escape $raw") }
            assertEquals(str(case["parsed"]), Cookies.unescape(str(case["wire"])), "unescape ${case["wire"]}")
        }
    }

    /** `Rack::Utils.escape` of every character to U+00FF and ruby_compat's edge cases, from `reference-tools/ruby_core.rb`. */
    @Test
    fun cookieEscapingIsRackEscape() {
        val rubyCore = MAPPER.readTree(File(VECTORS_DIR, "ruby_core.json"))
        val strings = rubyCore["strings"]
        assertTrue(strings.size() > 0)
        for (case in strings) {
            val raw = str(case["input"])
            assertEquals(str(case["rack_escape"]), Cookies.escape(raw), "escape $raw")
        }
    }

    @Test
    fun signedCookiesAreGeneratedByteForByte() {
        for (case in cases("signed_cookies.generate")) {
            val raw = Cookies.sign(SECRETS, str(case["name"]), str(case["value"]), optTime(case["expires_at"]))
            assertEquals(str(case["raw"]), raw, "value ${case["value"]}")
            val wire = str(case["set_cookie"]).substringBefore(';').substringAfter('=')
            assertEquals(wire, Cookies.escape(raw))
        }
    }

    @Test
    fun permanentCookiesExpireInTwentyYears() {
        val sessionToken = cases("signed_cookies.generate")[0]
        assertEquals(time(sessionToken["expires_at"]), Cookies.permanentExpiresAt(now()))
    }

    @Test
    fun signedCookiesVerifyLikeRails() {
        for (case in cases("signed_cookies.verify")) {
            val value = Cookies.verifySignedValue(SECRETS, str(case["name"]), str(case["raw"]), time(case["now"]))
            assertEquals(model(case["expected"]), value, label(case))
            val string = Cookies.verifySigned(SECRETS, str(case["name"]), str(case["raw"]), time(case["now"]))
            assertEquals(optStr(case["expected"]), string, label(case))
        }
    }

    @Test
    fun encryptedCookiesDecryptLikeRails() {
        for (case in cases("encrypted_cookies.verify")) {
            val value = Cookies.decrypt(SECRETS, str(case["name"]), str(case["raw"]), time(case["now"]))
            assertEquals(model(case["expected"]), value, label(case))
        }
    }

    @Test
    fun encryptedCookiePlaintextMatchesRails() {
        val encryptor = Cookies.encryptedCookieEncryptor(SECRETS)
        for (case in cases("encrypted_cookies.generate")) {
            val plaintext = assertNotNull(encryptor.decrypt(str(case["raw"])), "decrypts")
            assertEquals(str(case["plaintext"]), String(plaintext, Charsets.UTF_8))

            val ours = Metadata.serializeWithMetadata(
                Serializer.Null,
                RailsJson.encode(model(case["value"])),
                "cookie.${str(case["name"])}",
                optTime(case["expires_at"]),
            )
            assertEquals(str(case["plaintext"]), String(ours, Charsets.UTF_8))

            val raw = Cookies.encrypt(SECRETS, str(case["name"]), model(case["value"]), optTime(case["expires_at"]))
            assertEquals(model(case["value"]), Cookies.decrypt(SECRETS, str(case["name"]), raw, now()))
        }
    }

    @Test
    fun railsSessionAndItsFormsAreAccepted() {
        val session = v("session")
        assertEquals(302, session["post_with_form_token_status"].asInt())
        assertEquals(422, session["post_with_bad_token_status"].asInt())

        val hash = Cookies.decrypt(SECRETS, "_campfire_session", str(session["session_cookie_raw"]), now())
        assertNotNull(hash)
        assertEquals(model(session["session"]), hash)

        val token = str(session["session_token_value"])
        assertEquals(token, Cookies.verifySigned(SECRETS, "session_token", str(session["session_token_raw"]), now()))
        val ours = Cookies.sign(SECRETS, "session_token", token, Cookies.permanentExpiresAt(now()))
        assertEquals(str(session["session_token_raw"]), ours)
    }

    @Test
    fun signedIds() {
        for (case in cases("signed_ids.generate")) {
            val model = str(case["model"])
            val generated = SignedId.generate(SECRETS, model, case["id"].asLong(), optStr(case["purpose"]), optTime(case["expires_at"]))
            assertEquals(str(case["signed_id"]), generated, "$model ${case["id"]} ${case["purpose"]}")
        }
        for (case in cases("signed_ids.verify")) {
            val id = SignedId.verify(SECRETS, str(case["model"]), str(case["signed_id"]), optStr(case["purpose"]), time(case["now"]))
            val expected = case["expected"].let { if (it.isTextual) it.asText().toLong() else if (it.isIntegralNumber) it.asLong() else null }
            assertEquals(expected, id, label(case))
        }
    }

    @Test
    fun globalIds() {
        for (case in cases("global_ids")) {
            val gid = assertNotNull(GlobalId.parse(str(case["gid"])))
            assertEquals(GlobalId(str(case["model_name"]), str(case["id"])), gid)
            assertEquals(str(case["gid"]), gid.toString())
            assertEquals(str(case["param"]), gid.toParam())
        }
    }

    @Test
    fun sgids() {
        assertEquals(GlobalId.APP, str(v("sgids.app")))
        for (case in cases("sgids.generate")) {
            val gid = assertNotNull(GlobalId.parse(str(case["gid"])))
            val data = str(case["data"])
            val generated = if (data.endsWith("?expires_in")) {
                assertEquals(SignedGlobalId.ATTACHABLE_PURPOSE, str(case["purpose"]))
                SignedGlobalId.attachableSgid(SECRETS, gid)
            } else {
                SignedGlobalId.sgid(SECRETS, gid, str(case["purpose"]), optTime(case["expires_at"]))
            }
            assertEquals(str(case["sgid"]), generated, "$data for ${case["purpose"]}")
        }
        for (case in cases("sgids.verify")) {
            val located = SignedGlobalId.locateSigned(SECRETS, str(case["sgid"]), str(case["purpose"]), time(case["now"]))
            assertEquals(optStr(case["expected"])?.let(GlobalId::parse), located, label(case))
        }
    }

    @Test
    fun forgedSgidsAreRejected() {
        for (modelName in listOf("User", "Rooms::Open", "Account", "Message", "Rooms::Direct", "Session")) {
            val gid = GlobalId(modelName, 1)
            val forged = SignedGlobalId.verifier(Secrets("attacker")).generate(gid.toString(), "attachable", null)
            assertNull(SignedGlobalId.locateSigned(SECRETS, forged, "attachable", now()))
        }
    }

    @Test
    fun turboStreamNames() {
        for (case in cases("turbo_stream_names.generate")) {
            val parts = case["parts"].map { str(it) }
            assertEquals(str(case["stream_name"]), parts.joinToString(":"))
            assertEquals(str(case["signed"]), Turbo.signedStreamName(SECRETS, parts))
        }
        for (case in cases("turbo_stream_names.verify")) {
            val name = Turbo.verifiedStreamName(SECRETS, str(case["signed"]))
            val expected = case["expected"].let { if (it.isNull) null else if (it.isTextual) it.asText() else it.toString() }
            assertEquals(expected, name, label(case))
        }
    }

    @Test
    fun appVerifiers() {
        for (case in cases("app_verifiers.generate")) {
            val verifier = SECRETS.appVerifier(str(case["name"]))
            val message = verifier.generateRaw(str(case["data_json"]), optStr(case["purpose"]), optTime(case["expires_at"]))
            assertEquals(str(case["message"]), message, "${case["name"]} ${case["data_json"]}")
        }
        for (case in cases("app_verifiers.verify")) {
            val verifier = SECRETS.appVerifier(str(case["name"]))
            val data = verifier.verifyRaw(str(case["message"]), optStr(case["purpose"]), time(case["now"])).getOrNull()
            assertEquals(optStr(case["expected_json"]), data, label(case))
        }
    }

    /** Cost 12 takes a while per check, so the checks run side by side. */
    @Test
    fun passwords() {
        assertEquals(Password.COST, v("passwords.cost").asInt())
        for (case in cases("passwords.digests")) {
            assertTrue(str(case["digest"]).startsWith("\$2a\$12\$"))
        }
        val failures = cases("passwords.checks").parallelStream().map { case ->
            val ok = Password.verify(str(case["password"]), str(case["digest"]))
            if (ok == case["expected"].asBoolean()) null else "${case["password"]} against ${case["digest"]}: $ok"
        }.toList().filterNotNull()
        assertEquals(emptyList(), failures)
        assertTrue(Password.verify("secret123456", str(v("passwords.seeded_user_digest"))))
        val ours = Password.digestWithCost("pässwörd ☃", Password.MIN_COST)
        assertTrue(ours.startsWith("\$2a\$04\$") && Password.verify("pässwörd ☃", ours))
        assertFailsWith<IllegalArgumentException> { Password.digestWithCost("secret", Password.MIN_COST - 1) }
        assertFalse(Password.verify("anything", "not a digest"))
    }

    /** Writes Kotlin-generated values in the shape `reference-tools/rails_compat_verify_rust.rb` reads. */
    @Test
    fun writeKotlinOutputForRailsToVerify() {
        val now = now()
        val permanent = Cookies.permanentExpiresAt(now)
        val secrets = SECRETS

        val signedCookies = listOf("token-from-rust", "with space+plus/slash=", "<é&☃>", "").map { value ->
            linkedMapOf("name" to "session_token", "value" to value, "raw" to Cookies.sign(secrets, "session_token", value, permanent))
        } + listOf(linkedMapOf("name" to "other", "value" to "no expiry", "raw" to Cookies.sign(secrets, "other", "no expiry", null)))

        val encryptedCookies = listOf(
            linkedMapOf("session_id" to "rust-session-id", "return_to_after_authenticating" to "/rooms/1"),
            linkedMapOf("return_to_after_authenticating" to "http://campfire.test/rooms/1?a=1&b=<2>", "n" to 1L),
            "plain",
            listOf(1L, null, "☃ "),
        ).map { value ->
            linkedMapOf("name" to "_campfire_session", "raw" to Cookies.encrypt(secrets, "_campfire_session", value, permanent), "value" to value)
        }

        val sessionToken = "RustMadeSessionToken1234"

        val fourHours = now + Duration.ofHours(4)
        val signedIds = listOf(
            Triple(1L, "avatar", null),
            Triple(2L, "transfer", fourHours),
            Triple(12345L, null, null),
            Triple(9_007_199_254_740_993L, "avatar", null),
        ).map { (id, purpose, expiresAt) ->
            linkedMapOf("model" to "User", "id" to id, "purpose" to purpose, "signed_id" to SignedId.generate(secrets, "User", id, purpose, expiresAt))
        }

        val anHour = now + Duration.ofHours(1)
        val sgids = listOf(
            linkedMapOf("sgid" to SignedGlobalId.attachableSgid(secrets, GlobalId("User", 1)), "purpose" to "attachable", "expected" to "gid://campfire/User/1?expires_in"),
            linkedMapOf("sgid" to SignedGlobalId.attachableSgid(secrets, GlobalId("User", 2)), "purpose" to "attachable", "expected" to "gid://campfire/User/2?expires_in"),
            linkedMapOf("sgid" to SignedGlobalId.sgid(secrets, GlobalId("User", 1), "attachable", anHour), "purpose" to "attachable", "expected" to "gid://campfire/User/1"),
            linkedMapOf("sgid" to SignedGlobalId.sgid(secrets, GlobalId("Rooms::Open", 1), "default", null), "purpose" to "attachable", "expected" to null),
        )

        val room = GlobalId("Rooms::Open", 1).toParam()
        val user = GlobalId("User", 1).toParam()
        val turbo = listOf(listOf(room, "messages"), listOf("rooms"), listOf(user, "rooms"), listOf("unicode ☃ <&>")).map { parts ->
            linkedMapOf("signed" to Turbo.signedStreamName(secrets, parts), "expected" to parts.joinToString(":"))
        }

        val passwords = listOf("secret123456" to Password.COST, "pässwörd ☃" to Password.MIN_COST, "a".repeat(80) to Password.MIN_COST)
            .map { (pw, cost) -> linkedMapOf("password" to pw, "digest" to Password.digestWithCost(pw, cost)) }

        val appVerifiers = listOf(
            Triple(
                """{"key":"k1","disposition":"inline; filename=\"a&b.png\"","content_type":"image/png","service_name":"local"}""",
                "blob_key",
                fourHours,
            ),
            Triple("42", "blob_id", null),
            Triple("""{"z":1,"a":2}""", "x", null),
        ).map { (dataJson, purpose, expiresAt) ->
            linkedMapOf(
                "name" to "ActiveStorage",
                "data_json" to dataJson,
                "purpose" to purpose,
                "message" to secrets.appVerifier("ActiveStorage").generateRaw(dataJson, purpose, expiresAt),
            )
        }

        val output = linkedMapOf(
            "app_verifiers" to appVerifiers,
            "now" to str(v("now")),
            "signed_cookies" to signedCookies,
            "encrypted_cookies" to encryptedCookies,
            "session" to linkedMapOf(
                "session_token" to sessionToken,
                "session_token_cookie" to Cookies.sign(secrets, "session_token", sessionToken, permanent),
            ),
            "signed_ids" to signedIds,
            "sgids" to sgids,
            "turbo_stream_names" to turbo,
            "passwords" to passwords,
        )

        val path = File(VECTORS_DIR.parentFile, "rails-compat/build/rails_compat_kotlin_output.json")
        path.parentFile.mkdirs()
        path.writeText(MAPPER.copy().enable(SerializationFeature.INDENT_OUTPUT).writeValueAsString(output) + "\n")
        assertTrue(path.length() > 0)
    }
}
